import React from "react";
import { random } from "remotion";
import { palette } from "../theme/palette";
import { Flower, Leaf, type FlowerTone } from "../props/Florals";
import { cuspedArchPath } from "./WeddingDaySets";

/*
 * Floral sets for the Jaimaal (and reusable elsewhere): a dense rose-ivory-marigold flower wall
 * (as an SVG pattern, so it stays cheap), a jasmine-hung arch opening, a free-standing floral arch
 * frame, and the low stage.
 */

/** Pattern defs for the flower wall. Put inside an <svg>. */
export const FlowerWallDefs: React.FC<{ id: string; tint?: number }> = ({ id, tint = 0 }) => {
  const items: { x: number; y: number; r: number; tone: FlowerTone }[] = [
    { x: 18, y: 18, r: 17, tone: "rose" },
    { x: 66, y: 12, r: 14, tone: "ivory" },
    { x: 104, y: 30, r: 16, tone: "rose" },
    { x: 44, y: 50, r: 15, tone: "orange" },
    { x: 88, y: 70, r: 15, tone: "ivory" },
    { x: 14, y: 82, r: 14, tone: "ivory" },
    { x: 58, y: 96, r: 16, tone: "rose" },
    { x: 120, y: 100, r: 13, tone: "yellow" },
  ];
  return (
    <defs>
      <pattern id={id} width={128} height={116} patternUnits="userSpaceOnUse">
        <rect width={128} height={116} fill="#6E7B55" />
        {[0, 1, 2, 3, 4, 5].map((i) => (
          <Leaf key={i} x={10 + ((i * 47) % 120)} y={8 + ((i * 61) % 110)} rot={i * 67} s={1.6} color={i % 2 ? palette.green : palette.greenDeep} />
        ))}
        {items.map((f, i) => (
          <g key={i}>
            <Flower x={f.x} y={f.y} r={f.r} tone={f.tone} rot={i * 37} />
            {f.x + f.r > 128 ? <Flower x={f.x - 128} y={f.y} r={f.r} tone={f.tone} rot={i * 37} /> : null}
            {f.y + f.r > 116 ? <Flower x={f.x} y={f.y - 116} r={f.r} tone={f.tone} rot={i * 37} /> : null}
            {f.x - f.r < 0 ? <Flower x={f.x + 128} y={f.y} r={f.r} tone={f.tone} rot={i * 37} /> : null}
            {f.y - f.r < 0 ? <Flower x={f.x} y={f.y + 116} r={f.r} tone={f.tone} rot={i * 37} /> : null}
          </g>
        ))}
        {tint > 0 ? <rect width={128} height={116} fill="#FBF3E3" opacity={tint} /> : null}
      </pattern>
    </defs>
  );
};

/** Jasmine strands (small ivory blooms) hanging in a row. */
export const JasmineStrands: React.FC<{ x0: number; x1: number; y: (x: number) => number; bottom: number; n: number; seed: string; sway?: number }> = ({
  x0,
  x1,
  y,
  bottom,
  n,
  seed,
  sway = 0,
}) => (
  <g>
    {new Array(n).fill(0).map((_, i) => {
      const x = x0 + ((x1 - x0) * (i + 0.5)) / n;
      const top = y(x);
      const len = (bottom - top) * (0.55 + 0.45 * random(`${seed}${i}`));
      const m = Math.floor(len / 14);
      const sw = sway * Math.sin(i * 1.3);
      return (
        <g key={i}>
          <rect x={x - 0.4} y={top} width={0.8} height={len} fill={palette.goldLight} opacity={0.7} />
          {new Array(m).fill(0).map((__, j) => {
            const t = j / m;
            return <circle key={j} cx={x + sw * t * t} cy={top + 8 + j * 14} r={j % 5 === 4 ? 4.2 : 3.4} fill={j % 5 === 4 ? palette.roseLight : "#FFFDF6"} />;
          })}
          <circle cx={x + sw} cy={top + 8 + m * 14} r={4} fill="url(#foil)" />
        </g>
      );
    })}
  </g>
);

/** The flower wall with a cusped ivory arch opening, jasmine hung. Scene space. */
export const FlowerWall: React.FC<{ patternId: string; x0: number; x1: number; top: number; base: number; arch: { x: number; w: number; spring: number; apex: number }; sway?: number }> = ({
  patternId,
  x0,
  x1,
  top,
  base,
  arch,
  sway = 0,
}) => {
  const hole = cuspedArchPath(arch.x, arch.w, arch.spring, arch.apex, base, 7);
  const archCx = arch.x + arch.w / 2;
  // approximate the arch's inner top edge for hanging jasmine
  const archTop = (x: number) => {
    const u = Math.abs(x - archCx) / (arch.w / 2);
    return arch.apex + (arch.spring - arch.apex) * Math.pow(u, 1.6) + 16;
  };
  return (
    <g>
      {/* scalloped top edge made of blooms */}
      <path d={`M${x0} ${base} L${x0} ${top} L${x1} ${top} L${x1} ${base} Z ${hole}`} fill={`url(#${patternId})`} fillRule="evenodd" />
      <path d={`M${x0} ${base} L${x0} ${top} L${x1} ${top} L${x1} ${base} Z ${hole}`} fill="#3A2A18" fillRule="evenodd" opacity={0.08} />
      {new Array(Math.ceil((x1 - x0) / 34)).fill(0).map((_, i) => (
        <Flower key={i} x={x0 + 17 + i * 34} y={top} r={20} tone={i % 3 === 0 ? "ivory" : i % 3 === 1 ? "rose" : "orange"} rot={i * 29} />
      ))}
      {/* the opening: soft ivory drape */}
      <path d={hole} fill="#FBF1DE" />
      {[0.2, 0.4, 0.6, 0.8].map((k) => (
        <rect key={k} x={arch.x + arch.w * k - 1} y={arch.apex} width={2} height={base - arch.apex} fill={palette.ivoryShade} opacity={0.7} />
      ))}
      <JasmineStrands x0={arch.x + 20} x1={arch.x + arch.w - 20} y={archTop} bottom={arch.spring + 60} n={16} seed="jasmine" sway={sway} />
      <path d={hole} fill="none" stroke="url(#foil)" strokeWidth={4} />
      <path d={hole} fill="none" stroke={palette.ivoryLight} strokeWidth={1.5} transform="translate(0 -8)" opacity={0.6} />
    </g>
  );
};

/** Free-standing floral arch frame (posts + rounded top) built from dense blooms. */
export const FloralArchFrame: React.FC<{ x0: number; x1: number; base: number; top: number; seed: string; tones?: FlowerTone[]; r?: number }> = ({
  x0,
  x1,
  base,
  top,
  seed,
  tones = ["rose", "ivory", "orange", "rose", "ivory"],
  r = 22,
}) => {
  const w = x1 - x0;
  const spring = top + w * 0.5;
  const pts: [number, number][] = [];
  const step = r * 1.15;
  for (let y = base; y > spring; y -= step) pts.push([x0, y]);
  const arcN = Math.ceil((Math.PI * w * 0.5) / step);
  for (let i = 0; i <= arcN; i++) {
    const a = Math.PI + (i / arcN) * Math.PI;
    pts.push([x0 + w / 2 + Math.cos(a) * (w / 2), spring + Math.sin(a) * (w / 2) * ((spring - top) / (w / 2))]);
  }
  for (let y = spring; y <= base; y += step) pts.push([x1, y]);
  return (
    <g>
      {pts.map(([x, y], i) => (
        <Leaf key={`l${i}`} x={x + (random(`${seed}lx${i}`) - 0.5) * r} y={y} rot={random(`${seed}lr${i}`) * 360} s={r / 8} color={i % 2 ? palette.green : palette.greenDeep} />
      ))}
      {pts.map(([x, y], i) => (
        <Flower key={i} x={x + (random(`${seed}x${i}`) - 0.5) * r * 0.5} y={y} r={r * (0.85 + random(`${seed}r${i}`) * 0.35)} tone={tones[i % tones.length]} rot={random(`${seed}o${i}`) * 90} />
      ))}
    </g>
  );
};

/** Low stage: ivory top, maroon riser with gold diamonds. */
export const LowStage: React.FC<{ x0: number; x1: number; y: number; h?: number }> = ({ x0, x1, y, h = 70 }) => (
  <g>
    <path d={`M${x0 + 20} ${y} L${x1 - 20} ${y} L${x1} ${y + 22} L${x0} ${y + 22} Z`} fill={palette.ivoryLight} />
    <rect x={x0} y={y + 22} width={x1 - x0} height={h} fill={palette.maroon} />
    <rect x={x0} y={y + 22} width={x1 - x0} height={6} fill="url(#foil-h)" />
    <rect x={x0} y={y + 16 + h} width={x1 - x0} height={6} fill="url(#foil-h)" />
    {new Array(Math.floor((x1 - x0) / 60)).fill(0).map((_, i) => {
      const cx = x0 + 30 + i * 60;
      return <path key={i} d={`M${cx} ${y + 36} L${cx + 11} ${y + 22 + h / 2} L${cx} ${y + 8 + h} L${cx - 11} ${y + 22 + h / 2} Z`} fill="none" stroke={palette.gold} strokeWidth={1.3} />;
    })}
  </g>
);
